INSERT INTO public.truyen (id, title, author, cover_url, description, status, type, genres, total_chapters, rating, views, updated_at, search_text, moderation_status, owner_id) VALUES (34, 'Chiến Binh Cơ Giáp: Bầu Trời Sao Thứ Bảy', 'MechaCore Studio', 'https://picsum.photos/seed/novelreader-v2-34/300/450', '[Webtoon Sci-Fi Hành Động] Năm 2240, nhân loại xây dựng các колони trên quỹ đạo Sao Mộc. Phi công trẻ tuổi Hải Đăng điều khiển cỗ máy cơ giáp thế hệ cũ bảo vệ trạm không gian quê hương.', 'ongoing', 'comic', 'Hành động,Đô thị,Fantasy', 8, 4.8, 2090000, 1793400000000, 'chiến binh cơ giáp: bầu trời sao thứ bảy mechacore studio', 'approved', 1) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, total_chapters=EXCLUDED.total_chapters;

INSERT INTO public.chuong (id, novel_id, chapter_index, title, content) VALUES
(340001, 34, 1, 'Chap 1: Cỗ máy cơ giáp phủ bụi trong khoang chứa số 7', '【Chap 1 — Cỗ máy cơ giáp phủ bụi trong khoang chứa số 7】 (Chiến Binh Cơ Giáp: Bầu Trời Sao Thứ Bảy • Bản Truyện Tranh / Webtoon)
[img]https://picsum.photos/seed/manga-34-ch1-p1/720/1020[/img]
Trang 1/10 — Tiếng rồng gầm vọng lại từ dãy núi phía bắc. Đám lính gác trên tường thành nhìn nhau, bàn tay nắm chặt cán giáo không giấu nổi sự run rẩy.
[img]https://picsum.photos/seed/manga-34-ch1-p2/720/1020[/img]
Trang 2/10 — Khu rừng của tộc Elf tĩnh lặng đến lạ thường. Mỗi bước chân giẫm lên thảm lá đều như đang bị hàng trăm đôi mắt vô hình dõi theo từ tán cây cổ thụ.
[img]https://picsum.photos/seed/manga-34-ch1-p3/720/1020[/img]
Trang 3/10 — Viên ma thạch cấp cao tỏa ra luồng năng lượng tinh thuần, khiến không khí xung quanh cũng trở nên mát lạnh và trong trẻo hơn.
[img]https://picsum.photos/seed/manga-34-ch1-p4/720/1020[/img]
Trang 4/10 — 【Thoại】 “Hệ thống động cơ phản ứng đạt 120% công suất — Hải Đăng, xuất kích!”
[img]https://picsum.photos/seed/manga-34-ch1-p5/720/1020[/img]
Trang 5/10 — Mặt đất rung chuyển dưới những bước chân nặng nề. Bụi đá mù mịt bốc lên, báo hiệu trận chiến thực sự giờ mới bắt đầu.
[img]https://picsum.photos/seed/manga-34-ch1-p6/720/1020[/img]
Trang 6/10 — Thành phố về đêm rực rỡ ánh đèn neon. Giữa dòng người hối hả ngược xuôi, chẳng ai để ý đến chàng trai trẻ với ánh mắt trầm tĩnh ấy.
[img]https://picsum.photos/seed/manga-34-ch1-p7/720/1020[/img]
Trang 7/10 — Con hẻm nhỏ bán đồ ăn đêm vẫn tấp nập khách quen, mùi phở nóng và tiếng trò chuyện rôm rả xua tan cái mệt mỏi của một ngày dài.
[img]https://picsum.photos/seed/manga-34-ch1-p8/720/1020[/img]
Trang 8/10 — Tiếng rồng gầm vọng lại từ dãy núi phía bắc. Đám lính gác trên tường thành nhìn nhau, bàn tay nắm chặt cán giáo không giấu nổi sự run rẩy.
[img]https://picsum.photos/seed/manga-34-ch1-p9/720/1020[/img]
Trang 9/10 — Khu rừng của tộc Elf tĩnh lặng đến lạ thường. Mỗi bước chân giẫm lên thảm lá đều như đang bị hàng trăm đôi mắt vô hình dõi theo từ tán cây cổ thụ.
[img]https://picsum.photos/seed/manga-34-ch1-p10/720/1020[/img]
Trang 10/10 — Viên ma thạch cấp cao tỏa ra luồng năng lượng tinh thuần, khiến không khí xung quanh cũng trở nên mát lạnh và trong trẻo hơn.
— Hết Chap 1: Cỗ máy cơ giáp phủ bụi trong khoang chứa số 7 —'),
(340002, 34, 2, 'Chap 2: Tín hiệu báo động từ vành đai tiểu hành tinh', '【Chap 2 — Tín hiệu báo động từ vành đai tiểu hành tinh】 (Chiến Binh Cơ Giáp: Bầu Trời Sao Thứ Bảy • Bản Truyện Tranh / Webtoon)
